async function loadCategory(k,lang,limit=10){
  const qs=(CATEGORY_QUERIES[k]||[k]).slice(0,k==="latest"?4:3);
  const sets=await Promise.all(qs.map(q=>searchFeed(q,lang)));
  let items=uniq(sets.flat());
  if(k!=="latest"){
    const matched=items.filter(x=>categoryRelevant(x,k,lang));
    if(matched.length>=3)items=matched;
  }
  items.sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0));
  return items.slice(0,limit);
}
async function news(lang){
  const previous=await readNewsArchive(lang);
  const cleanOld=(a)=>Array.isArray(a)?a.filter(validStory):[];
  const keys=Object.keys(CATS);
  const pairs=await Promise.all(keys.map(async k=>[k,await loadCategory(k,lang,k==="latest"?24:8)]));
  const fresh=Object.fromEntries(pairs);
  const out={};
  for(const k of keys){
    const old=cleanOld(previous?.[k]);
    out[k]=uniq([...(fresh[k]||[]),...old]).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0)).slice(0,k==="latest"?60:24);
  }
  const latest=uniq(keys.filter(k=>k!=="latest").flatMap(k=>cleanOld(out[k]||[]))).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0));
  out.latest=uniq([...(fresh.latest||[]).filter(validStory),...latest,...cleanOld(previous?.latest)]).filter(validStory).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0)).slice(0,60);
  await writeNewsArchive(lang,out);
  return out;
}
async function markets(){
  const d={fx:{},gold:{},updated:new Date().toISOString(),source:"Frankfurter + XAU"};
  try{
    const rows=await getJson("https://api.frankfurter.dev/v2/rates?base=EGP&quotes=USD,EUR,GBP,SAR,AED");
    for(const row of Array.isArray(rows)?rows:[]){
      const key=String(row?.quote||"").toLowerCase(),r=Number(row?.rate);
      if(key&&r>0){
        const mid=1/r;
        d.fx[key]={mid,buy:mid*1.0025,sell:mid*0.9975};
      }
    }
  }catch{}
  let oz=null;
  try{oz=Number((await getJson("https://api.frankfurter.dev/v2/rate/xau/usd"))?.rate)}catch{}
  if(!(oz>0)){
    try{oz=Number((await getJson("https://api.gold-api.com/price/XAU"))?.price)}catch{}
  }
  const usd=d.fx.usd?.mid;
  if(oz>0&&usd>0){
    const egpOz=oz*usd,g24=egpOz/31.1034768,gold={};
    [["24K",g24],["21K",g24*21/24],["18K",g24*18/24],["Coin",g24*21/24*8],["Ounce",egpOz]].forEach(([name,v])=>{
      gold[name]={mid:v,buy:v*1.008,sell:v*0.995};
    });
    gold.World={mid:oz,buy:oz*1.002,sell:oz*0.998,currency:"USD"};
    d.gold=gold;
  }
  return d;
}
