async function search(q,lang){const a=await searchFeed(q,lang);let w=[];try{const base=lang==="ar"?"https://ar.wikipedia.org/w/rest.php/v1/search/page?q=":"https://en.wikipedia.org/w/rest.php/v1/search/page?q=";const d=await getJson(base+encodeURIComponent(q)+"&limit=8");w=(d.pages||[]).map(x=>({id:enc(JSON.stringify({title:x.title,description:strip(x.description||x.excerpt||""),date:"",link:(lang==="ar"?"https://ar.wikipedia.org/wiki/":"https://en.wikipedia.org/wiki/")+encodeURIComponent(x.key||x.title),source:"Wikipedia",image:url(x?.thumbnail?.url)})),title:x.title,description:strip(x.description||x.excerpt||""),link:(lang==="ar"?"https://ar.wikipedia.org/wiki/":"https://en.wikipedia.org/wiki/")+encodeURIComponent(x.key||x.title),source:"Wikipedia",image:url(x?.thumbnail?.url)}))}catch{}const out=uniq(a.concat(w)).filter(validStory).slice(0,18);return out}
